<?php
define( 'ABSPATH', __DIR__ . '/' );
require __DIR__ . '/../../wp-content/mu-plugins/dsa/includes/Bricks/Compiler_Package_Error.php';
require __DIR__ . '/../../wp-content/mu-plugins/dsa/includes/Bricks/Framework_Style_Service.php';
use DSA\Bricks\Framework_Style_Service as Styles;
$checks = 0;
$check = static function( bool $ok,string $name ) use ( &$checks ): void { if ( ! $ok ) throw new RuntimeException( $name ); $checks++; };
$reject = static function( callable $call,string $name ) use ( $check ): void { $failed = false; try { $call(); } catch ( DSA\Bricks\Compiler_Package_Error $error ) { $failed = true; } $check( $failed,$name ); };
$before = [];
foreach ( [ 'variables','categories','colorPalette','classes','classCategories','themeStyles' ] as $kind ) $before[$kind] = [ 'exists'=>false,'value'=>[] ];
$old = [ 'id'=>'old-card','name'=>'other-card','settings'=>[ '_padding'=>'12px' ],'source'=>'kiwe-project','project'=>'previous' ];
$before['classes'] = [ 'exists'=>true,'value'=>[ $old ] ];
$incoming = [ 'id'=>'new-card','name'=>'next-card','settings'=>[ '_padding'=>'18px' ],'source'=>'kiwe-project','project'=>'next' ];
$plan = Styles::plan( $before,[],[ 'classes'=>[ $incoming ] ] );
$check( $plan['after']['classes']['value'] === [ $old,$incoming ],'A new project never removes existing project classes' );
$check( $before['classes']['value'] === [ $old ],'Planning leaves native input untouched' );
$same = Styles::plan( $plan['after'],[],[ 'classes'=>[ $incoming ] ] );
$check( $same['before'] === $same['after'] && $same['reused'] === 1,'Repeated installation reuses identical styles' );
$updated = $incoming; $updated['settings']['_padding'] = '20px';
$check( Styles::plan( $plan['after'],[],[ 'classes'=>[ $updated ] ] )['after']['classes']['value'] === [ $old,$updated ],'Only the matching managed project entry updates' );
$foreign = $updated; $foreign['project'] = 'foreign';
$reject( static fn()=>Styles::plan( $plan['after'],[],[ 'classes'=>[ $foreign ] ] ),'Different owner cannot overwrite a matching style ID' );
$collision = $incoming; $collision['id'] = 'different-id';
$reject( static fn()=>Styles::plan( $plan['after'],[],[ 'classes'=>[ $collision ] ] ),'Class-name collision cannot silently disconnect native IDs' );
$user = $before; $user['variables'] = [ 'exists'=>true,'value'=>[ [ 'id'=>'native-user','name'=>'card-space','value'=>'18px' ] ] ];
$variable = [ 'id'=>'new-space','name'=>'card-space','value'=>'18px','source'=>'kiwe-project','project'=>'next' ];
$check( Styles::plan( $user,[],[ 'variables'=>[ $variable ] ] )['after']['variables'] === $user['variables'],'Equivalent variable name/value reuses the actual native entry' );
$variable['value'] = '22px';
$reject( static fn()=>Styles::plan( $user,[],[ 'variables'=>[ $variable ] ] ),'A different value cannot overwrite a client-owned variable' );
$theme = [ 'themeStyle'=>[ 'id'=>'existing','label'=>'Client design','settings'=>[ 'font'=>'new' ] ] ];
$before['themeStyles'] = [ 'exists'=>true,'value'=>[ 'existing'=>[ 'label'=>'Client design','settings'=>[ 'font'=>'old' ] ] ] ];
$reject( static fn()=>Styles::plan( $before,$theme,[] ),'Compiler import cannot silently change an existing Theme Style' );
$check( Styles::plan( $before,$theme,[],true,true )['changes'][0]['action'] === 'update-shared','Explicit manual push retains its reviewed Theme Style update capability' );
$palette = [ 'id'=>'new-palette','name'=>'New project palette','source'=>'kiwe-project','project'=>'next','colors'=>[ [ 'id'=>'color-1','light'=>'#eedddd','dark'=>'#331111','raw'=>'var(--project-tone)' ] ] ];
$before['colorPalette'] = [ 'exists'=>true,'value'=>[ [ 'id'=>'client-palette','name'=>'Client palette','colors'=>[ [ 'light'=>'#eeeeee','dark'=>'#111111' ] ] ] ] ];
$palettes = Styles::plan( $before,[],[ 'colorPalette'=>[ $palette ] ] );
$check( $palettes['after']['colorPalette']['value'][0] === $before['colorPalette']['value'][0],'Client light/dark palette survives a new project import exactly' );
$check( $palettes['after']['colorPalette']['value'][1] === $palette,'Project light/dark entries and variable references survive the native merge exactly' );

$canonical = [ 'id'=>'shared-seam','name'=>'seam-print-hidden','settings'=>[],'source'=>'kiwe-seam','category'=>'state' ];
$duplicate = $canonical; $duplicate['category'] = 'utility';
$legacy = $before; $legacy['classes'] = [ 'exists'=>true,'value'=>[ $canonical,$duplicate ] ];
$reuse = Styles::plan( $legacy,[ 'classes'=>[ $canonical ] ],[] );
$check( $reuse['after'] === $legacy && $reuse['reused'] === 1,'Equivalent legacy Kiwe vocabulary duplicates are retained byte-for-byte and reused' );
$edited = $legacy; $edited['classes']['value'][1]['settings']['_opacity'] = '0.5';
$reject( static fn()=>Styles::plan( $edited,[ 'classes'=>[ $canonical ] ],[] ),'A later native edit cannot be bypassed as an equivalent legacy duplicate' );
$foreign_duplicate = $legacy; $foreign_duplicate['classes']['value'][1]['source'] = 'client';
$reject( static fn()=>Styles::plan( $foreign_duplicate,[ 'classes'=>[ $canonical ] ],[] ),'A duplicate owned by another editor is not adopted by Kiwe' );
$renamed_duplicate = $legacy; $renamed_duplicate['classes']['value'][1]['name'] = 'client-print';
$reject( static fn()=>Styles::plan( $renamed_duplicate,[ 'classes'=>[ $canonical ] ],[] ),'A duplicate native ID with another name remains blocked' );
echo json_encode( [ 'schema'=>'kiwe.sc02.style-merge-tests.v1','passed'=>true,'checks'=>$checks,'mutatesWordPress'=>false ] ) . PHP_EOL;
